// Ruhezustand. Beide Sicherungen stehen: leerer Namensfilter trifft
// nichts, und probelauf zeigt nur, was er taete. Vor jedem Einsatz
// erst den Filter setzen, dann probelauf abschalten.
const s = {
  driveId: 'b!C2yhEx592Ei36yvay6U9n2886_vvW61LokJwBCKhlW_uiHYCBMlCRaEn9mGTdB1m',
  driveName: 'Dokumente (Shared Documents) der Site rwgintranet',

  quellPfad: '/IMPORTER/CONTRACT/FEHLER',
  zielPfad: '/IMPORTER/CONTRACT',

  // Mehrere Namensteile durch Komma getrennt. Leer trifft nichts.
  nurDatei: '',

  probelauf: true
};

const basis = 'https://graph.microsoft.com/v1.0/drives/' + s.driveId;
s.basis = basis;
s.urlQuelle = basis + '/root:' + s.quellPfad + ':/children?$top=500';
s.urlZiel = basis + '/root:' + s.zielPfad;

return [{ json: { _steuerung: s } }];

const s = $('Steuerung').first().json._steuerung;
const kinder = $('Quelle lesen').first().json.value || [];
const ziel = $('Ziel lesen').first().json || {};
const zielId = ziel.id ? String(ziel.id) : '';

if (!zielId) {
  throw new Error('ZIELORDNER_UNBEKANNT: ' + s.zielPfad + ' - Graph hat keine Item-ID geliefert.');
}

const dateien = kinder.filter(k => k && k.file);

// Mehrere Namensteile, durch Komma getrennt. Eine leere Liste trifft
// nichts - Absicht, keine Luecke.
const filterListe = String(s.nurDatei || '')
  .split(',')
  .map(f => f.trim().toLowerCase())
  .filter(Boolean);

const treffer = filterListe.length
  ? dateien.filter(k => filterListe.some(f => String(k.name).toLowerCase().indexOf(f) !== -1))
  : [];

if (!treffer.length) {
  return [{ json: {
    aktion: 'nichts',
    grund: filterListe.length
      ? 'Kein Treffer fuer den Namensfilter: ' + filterListe.join(', ')
      : 'Kein Namensfilter gesetzt - es wird nichts angefasst.',
    quelle: s.quellPfad,
    ziel: s.zielPfad,
    dateien_im_quellordner: dateien.length,
    namen_im_quellordner: dateien.map(k => k.name).slice(0, 20)
  } }];
}

return treffer.map(k => ({ json: {
  aktion: s.probelauf === true ? 'probelauf' : 'verschieben',
  datei: k.name,
  item_id: k.id,
  bytes: Number(k.size || 0),
  quelle: s.quellPfad,
  ziel: s.zielPfad,
  ziel_id: zielId,
  url_verschieben: s.basis + '/items/' + k.id
} }));

const s = $('Steuerung').first().json._steuerung;
const auftraege = $('Auftrag bauen').all().map(i => i.json);

const geplant = auftraege.filter(a => a.aktion === 'verschieben');
const probe = auftraege.filter(a => a.aktion === 'probelauf');
const leer = auftraege.filter(a => a.aktion === 'nichts');

return [{ json: {
  probelauf: s.probelauf === true,
  quelle: s.quellPfad,
  ziel: s.zielPfad,
  namensfilter: s.nurDatei || '(leer)',
  verschoben: geplant.map(a => a.datei),
  wuerde_verschieben: probe.map(a => a.datei),
  hinweis: leer.length ? leer[0].grund : null,
  namen_im_quellordner: leer.length ? leer[0].namen_im_quellordner : undefined,
  anzahl: geplant.length + probe.length
} }];
